# AtomicAndPhysicalConstants/src/CODATA2018.jl
# Constants pulled from the NIST table of
# the 2018 CODATA release
# Generated by update/update_constants.jl; masses are NIST's
# "energy equivalent in MeV" values with the decimal point moved to eV.



#####################################################################
# Physical constants
#####################################################################


"""
    CODATA2018 :: CODATA_release

Fundamental constants from the 2018 CODATA release.

See [NIST CODATA](https://physics.nist.gov/cuu/Constants/) for the
primary source values.
"""
const CODATA2018 = CODATA_release(

#######################################
# constants with dimension [mass]
#######################################


M_ELECTRON = 510998.95,
# Electron Mass [eV]/c^2
M_PROTON = 9.3827208816e8,
# Proton Mass [eV]/c^2
M_NEUTRON = 9.3956542052e8,
# Neutron Mass [eV]/c^2
M_MUON = 1.056583755e8,
# Muon Mass [eV]/c^2
M_HELION = 2.80839160743e9,
# Helion Mass He3 nucleus [eV]/c^2
M_DEUTERON = 1.87561294257e9,
# Deuteron Mass [eV]/c^2
M_TRITON = 2.80892113298e9,
# Triton Mass [eV]/c^2

# not tabulated by CODATA; fit values from the 2018 edition of the
# PDG Review of Particle Physics
M_PION_0 = 1.349770445888749e8,
# uncharged pion mass [eV]/c^2
M_PION_CHARGED = 1.395706078048715e8,
# charged pion mass [eV]/c^2


#######################################
# constants with dimension [magnetic moment]
#######################################


MU_DEUTERON = 4.330735094e-27,
