#######################################
# constants with miscellaneous dimension
#######################################


E_CHARGE = 1.602176634e-19,
# elementary charge [C]
R_ELECTRON = 2.8179403262e-15,
# classical electron radius [m]
R_PROTON = 1.5346982671888944e-18,
